async function showDetail(kind,id){let object;if(kind==='requirement'){object=state.allRequirements.find(x=>x.requirement_set_id===id)||state.requirements.find(x=>x.requirement_set_id===id);const counts=requirementCounts(object||{}),project=state.projects.find(x=>x.project_id===object?.project_id);openDrawer(`RequirementSet V${object?.version||'—'}`,'IMMUTABLE DATA CONTRACT',`<div class="contract-list"><div><span>Project</span><strong>${esc(project?.title||object?.project_id)}</strong></div><div><span>Status</span><strong>${esc(object?.status)}</strong></div><div><span>Derived / Manual / Effective</span><strong>${counts.derived} / ${counts.manual} / ${counts.effective}</strong></div><div><span>Fields</span><strong>${esc(counts.fields.join(', '))}</strong></div><div><span>Created</span><strong>${esc(object?.created_at)}</strong></div></div><div class="form-actions drawer-actions"><button data-action="open-requirement" data-id="${esc(id)}">在项目查看</button><button class="primary" data-action="edit-requirement" data-id="${esc(id)}">编辑为新版本</button></div><details class="advanced-panel"><summary>Advanced · Complete Contract</summary><pre class="json-view">${esc(json(object))}</pre></details>`);return}else if(kind==='definition'){object=state.definitions.find(x=>x.definition_id===id);openDrawer(object?.name||short(id,24),'DEFINITION / IMPACT','<p class="muted">正在计算影响范围…</p>');try{const impact=await api(`/api/research/definitions/${encodeURIComponent(id)}/impact`);$('drawerBody').innerHTML=`<div class="contract-list"><div><span>Project references</span><strong>${impact.project_references.length}</strong></div><div><span>Alpha dependents</span><strong>${impact.alpha_dependents.length}</strong></div><div><span>Historical runs</span><strong>${impact.historical_run_ids.length}</strong></div><div><span>历史 Run 被修改</span><strong>NO</strong></div></div><details class="advanced-panel"><summary>Advanced · Technical Contract</summary><pre class="json-view">${esc(json(object))}</pre></details>`}catch(error){$('drawerBody').innerHTML=`<p class="muted">${esc(error.message)}</p>`}return}else if(kind==='snapshot'){object=state.snapshots.find(x=>x.universe_snapshot_id===id);const universe=state.universes.find(x=>x.universe_definition_id===object?.universe_definition_id);openDrawer(universe?.name||short(id,24),'UNIVERSE SNAPSHOT',`<div class="contract-list"><div><span>Definition</span><strong>${esc(universe?.name)} @ ${esc(universe?.version)}</strong></div><div><span>Snapshot As-of</span><strong>${esc(object?.as_of_time)}</strong></div><div><span>Members</span><strong>${arr(object?.actual_instrument_ids).length}</strong></div></div><div class="member-list">${arr(object?.actual_instrument_ids).map(x=>`<span>${esc(x)}</span>`).join('')}</div><details class="advanced-panel"><summary>Advanced · IDs / Fingerprint</summary><pre class="json-view">${esc(json(object))}</pre></details>`);return}else if(kind==='run')object=state.runs.find(x=>x.run_id===id);else{object=state.universes.find(x=>x.universe_definition_id===id);const snapshots=state.snapshots.filter(x=>x.universe_definition_id===id);openDrawer(object?.name||short(id,24),'UNIVERSE DEFINITION',`<div class="contract-list"><div><span>Version / Type</span><strong>${esc(object?.version)} · ${esc(object?.universe_type)}</strong></div><div><span>State</span><strong>${esc(object?.status)}</strong></div><div><span>Snapshots</span><strong>${snapshots.length}</strong></div></div><div class="object-list">${snapshots.map(x=>`<button class="object-row" data-detail="snapshot" data-id="${esc(x.universe_snapshot_id)}"><span>${esc(x.as_of_time)}</span><strong>${arr(x.actual_instrument_ids).length} members</strong></button>`).join('')}</div><details class="advanced-panel"><summary>Advanced · Technical Contract</summary><pre class="json-view">${esc(json(object))}</pre></details>`);return}openDrawer(object?.name||short(id,24),kind.toUpperCase(),`<pre class="json-view">${esc(json(object))}</pre>`)}
