function toLocalDateTime(value,fallback){const date=value?new Date(value):fallback;if(!date||Number.isNaN(date.getTime()))return'';const copy=new Date(date);copy.setMinutes(copy.getMinutes()-copy.getTimezoneOffset());return copy.toISOString().slice(0,16)}
function selectedOption(value,current){return String(value)===String(current)?'selected':''}
function requirementDialog(base=latestRequirement()){
  const factorRefs=Object.values(state.refs).filter(x=>x.definition_type==='FACTOR'&&x.reference_mode==='PINNED'),context=base?.context||{},sources=arr(base?.source_specs);
  const manualFields=[...new Set(sources.filter(x=>x.origin_type==='MANUAL').flatMap(x=>arr(x.spec?.fields)))];
  const executionFields=[...new Set(sources.filter(x=>x.origin_type==='BACKTEST_SPEC').flatMap(x=>arr(x.spec?.fields)))];
  const projectSnapshots=snapshotsForProject(),contextInstruments=new Set(arr(context.instrument_ids)),matchedSnapshot=projectSnapshots.find(x=>x.universe_snapshot_id===context.universe_snapshot_id)||projectSnapshots.find(x=>{const members=arr(x.actual_instrument_ids);return members.length===contextInstruments.size&&members.every(y=>contextInstruments.has(y))})||projectSnapshots[0];
  const nextVersion=Math.max(0,...state.requirements.map(x=>Number(x.version)||0))+1;
  openDialog(base?`编辑 RequirementSet V${base.version} → V${nextVersion}`:'创建 RequirementSet','REQUIREMENTSET LIBRARY / NEW IMMUTABLE VERSION',`<form id="requirementForm" class="form-stack">
    <div class="immutable-banner"><strong>版本规则</strong><span>V${esc(base?.version||'—')} 保持不可变；保存后编译 V${esc(nextVersion)}，旧 Preview/Bundle/Run 继续引用原版本。</span></div>
    <div class="editor-layout"><div class="form-stack">
      <section class="form-section"><h3>Definition Context</h3><label>Universe Snapshot<select id="reqSnapshot" required>${option(projectSnapshots,x=>x.universe_snapshot_id,x=>`${state.universes.find(u=>u.universe_definition_id===x.universe_definition_id)?.name||'Universe'} · ${arr(x.actual_instrument_ids).length} 个标的 · ${x.as_of_time}`)}</select></label><div class="form-grid"><label>数据类型<select id="reqDataType"><option value="bars" ${selectedOption('bars',context.data_type||'bars')}>Bars</option></select></label><label>频率<select id="reqFrequency">${['1m','5m','15m','1h','4h','1d'].map(x=>`<option ${selectedOption(x,context.frequency||'1h')}>${x}</option>`).join('')}</select></label><label>历史开始<input id="reqStart" type="datetime-local" required value="${esc(toLocalDateTime(context.history_start,new Date(Date.now()-90*86400000)))}"></label><label>历史结束<input id="reqEnd" type="datetime-local" value="${esc(toLocalDateTime(context.history_end,new Date()))}"></label></div></section>
      <section class="form-section"><h3>Data Semantics</h3><div class="form-grid"><label>复权策略<select id="reqAdjustment"><option ${selectedOption('NONE',context.adjustment||'NONE')}>NONE</option><option ${selectedOption('SPLIT_ADJUSTED',context.adjustment)}>SPLIT_ADJUSTED</option></select></label><label>Point-in-time<select id="reqPit"><option ${selectedOption('AS_OF',context.point_in_time_policy||'AS_OF')}>AS_OF</option><option ${selectedOption('LATEST',context.point_in_time_policy)}>LATEST</option></select></label><label>质量策略<select id="reqQuality"><option ${selectedOption('STRICT',context.quality_policy||'STRICT')}>STRICT</option><option ${selectedOption('WARN',context.quality_policy)}>WARN</option></select></label><label>来源策略<select id="reqSourcePolicy"><option ${selectedOption('FIXED',context.source_policy||'FIXED')}>FIXED</option><option ${selectedOption('PREFERRED',context.source_policy)}>PREFERRED</option></select></label><label>时间语义<input id="reqTimeSemantics" value="${esc(context.time_semantics||'BAR_END_AVAILABLE_TIME')}" readonly></label></div></section>
      <section class="form-section"><h3>Manual Requirements</h3><label>人工补充字段<input id="reqManual" value="${esc(manualFields.join(', '))}" placeholder="volume, quote_volume, trade_count"></label><label>执行 / 回测字段<input id="reqExecutionFields" value="${esc((executionFields.length?executionFields:['open']).join(', '))}" placeholder="open"></label><p class="field-help">添加、修改或删除字段后会生成新版本。清空“人工补充字段”即在新版本停用 Manual；Derived 字段仍由当前 PINNED Factor 自动生成。</p></section>
      <section class="form-section"><h3>Derived Closure</h3><div class="object-list">${factorRefs.map(x=>`<div class="object-row"><div class="object-main"><strong>${esc(x.name)} @ ${esc(x.definition_version)}</strong><small>${esc(x.spec?.formula?.operator)} · ${esc(x.spec?.formula?.input)} · Warmup ${esc(x.spec?.minimum_observations)}</small></div>${chip('LOCKED')}</div>`).join('')||'<p class="field-help">当前项目没有 PINNED Factor；仍可创建只包含 Manual / Backtest 字段的 RequirementSet。</p>'}</div></section>
    </div><div class="editor-side"><pre id="requirementSource" class="source-preview"></pre><div class="contract-list"><div><span>Derived</span><strong>系统生成，不可直接编辑</strong></div><div><span>Manual</span><strong>新版本可编辑</strong></div><div><span>Effective</span><strong>编译时确定性合并</strong></div><div><span>Historical versions</span><strong>永不覆盖</strong></div></div></div></div>
    <div class="form-actions"><button type="button" data-action="open-requirement-library">取消并查看 Library</button><button type="submit" class="primary" ${matchedSnapshot?'':'disabled'}>编译并保存 V${esc(nextVersion)}</button></div></form>`);
  if(matchedSnapshot)$('reqSnapshot').value=matchedSnapshot.universe_snapshot_id;
  const updateSource=()=>{const snapshot=state.snapshots.find(x=>x.universe_snapshot_id===$('reqSnapshot').value);$('requirementSource').textContent=`requirement_set: V${nextVersion}\nproject: ${state.project?.title||state.projectId}\nuniverse_members: ${arr(snapshot?.actual_instrument_ids).length}\ndata: ${$('reqDataType').value} @ ${$('reqFrequency').value}\nhistory: ${$('reqStart').value} → ${$('reqEnd').value||'OPEN'}\nsemantics: ${$('reqAdjustment').value} / ${$('reqPit').value} / ${$('reqQuality').value}\nderived_factors: ${factorRefs.length}\nmanual_fields: ${$('reqManual').value||'none'}\nexecution_fields: ${$('reqExecutionFields').value||'none'}`};
  $('requirementForm').addEventListener('input',updateSource);updateSource();
  $('requirementForm').addEventListener('submit',async event=>{event.preventDefault();try{const snapshot=state.snapshots.find(x=>x.universe_snapshot_id===$('reqSnapshot').value),split=id=>$(id).value.split(/[\s,]+/).filter(Boolean),manual=split('reqManual'),executionFields=split('reqExecutionFields');const payload={context:{universe_snapshot_id:snapshot.universe_snapshot_id,instrument_ids:snapshot.actual_instrument_ids,data_type:$('reqDataType').value,frequency:$('reqFrequency').value,history_start:new Date($('reqStart').value).toISOString(),history_end:$('reqEnd').value?new Date($('reqEnd').value).toISOString():null,adjustment:$('reqAdjustment').value,time_semantics:$('reqTimeSemantics').value,point_in_time_policy:$('reqPit').value,quality_policy:$('reqQuality').value,source_policy:$('reqSourcePolicy').value},factor_specs:factorRefs.map(x=>x.spec),manual_requirements:manual.length?[{id:'manual_supplement',fields:manual,dependency_path:['Manual',...manual]}]:[],evaluation_requirements:[],backtest_requirements:executionFields.length?[{id:'execution_fields',fields:executionFields,lookback_value:1,dependency_path:['Backtest',...executionFields]}]:[],universe_requirements:[]};const created=await api(`/api/research/projects/${encodeURIComponent(state.projectId)}/requirement-sets`,{method:'POST',body:JSON.stringify(payload)});state.selectedRequirementId=created.requirement_set_id;$('editorDialog').close();await loadBase();switchView('projects');switchTab('requirements');notify(`RequirementSet V${created.version} 已保存；旧版本保持不可变`)}catch(error){notify(error.message,true)}})
}
async function openRequirementInProject(id,edit=false){const req=state.allRequirements.find(x=>x.requirement_set_id===id)||state.requirements.find(x=>x.requirement_set_id===id);if(!req)return;try{closeDrawer();if(state.projectId!==req.project_id)await loadProject(req.project_id);state.selectedRequirementId=id;switchView('projects');switchTab('requirements');if(edit)requirementDialog(req)}catch(error){notify(error.message,true)}}
async function openRequirementProject(projectId){try{if(state.projectId!==projectId)await loadProject(projectId);switchView('projects');switchTab('requirements')}catch(error){notify(error.message,true)}}
async function openProject(projectId){try{if(state.projectId!==projectId)await loadProject(projectId);switchView('projects');switchTab('overview')}catch(error){notify(error.message,true)}}

document.addEventListener('click',event=>{
  const view=event.target.closest('[data-view]')?.dataset.view;if(view){switchView(view);return}
  const tab=event.target.closest('[data-tab]')?.dataset.tab;if(tab){switchTab(tab);return}
  const mode=event.target.closest('[data-requirement-mode]')?.dataset.requirementMode;if(mode){requirementMode=mode;renderRequirementsTab();return}
  const detail=event.target.closest('[data-detail]');if(detail){if(detail.dataset.detail==='run')showRunResult(detail.dataset.id);else showDetail(detail.dataset.detail,detail.dataset.id);return}
  const actionNode=event.target.closest('[data-action]'),action=actionNode?.dataset.action;if(!action)return;
  if(action==='new-project')newProjectDialog();else if(action==='open-project')openProject(actionNode.dataset.projectId);else if(action==='new-factor')factorDialog();else if(action==='new-alpha')alphaDialog();else if(action==='new-version'){const d=state.definitions.find(x=>x.definition_id===actionNode.dataset.id);if(d?.definition_type==='FACTOR')factorDialog(d);else if(d)alphaDialog(d)}else if(action==='fork-universe'){universeDialog(state.universes.find(x=>x.universe_definition_id===actionNode.dataset.id))}else if(action==='validate-definition')validateDefinition(actionNode.dataset.id);else if(action==='pin-definition')pinDefinition(actionNode.dataset.id,actionNode.dataset.version);else if(action==='create-run')createRun();else if(action==='execute-run')executeQueuedRun();else if(action==='approve-run-scope')grantDialog();else if(action==='toggle-agent')toggleAgent(actionNode.dataset.paused==='1');else if(action==='readiness-detail')showReadiness(actionNode.dataset.dimension);else if(action==='resolved-plan')showResolvedPlan();else if(action==='open-inputs')switchTab('inputs');else if(action==='open-universe-library')switchView('universe-library');else if(action==='open-requirement-library'){if($('editorDialog').open)$('editorDialog').close();switchView('requirement-library')}else if(action==='open-factor-library')switchView('factor-library');else if(action==='open-alpha-library')switchView('alpha-library');else if(action==='compile-requirements')requirementDialog();else if(action==='edit-requirement')openRequirementInProject(actionNode.dataset.id,true);else if(action==='open-requirement')openRequirementInProject(actionNode.dataset.id,false);else if(action==='open-requirement-project')openRequirementProject(actionNode.dataset.projectId);else if(action==='check-requirement-coverage')checkRequirementCoverage(actionNode.dataset.id);else if(action==='new-universe')universeDialog()
});
$('projectTabs').addEventListener('click',e=>{const tab=e.target.dataset.tab;if(tab)switchTab(tab)});
$('projectSelect').addEventListener('change',async e=>{state.projectId=e.target.value;if(state.projectId)await loadProject(state.projectId);else{state.project=null;state.preview=null;renderProject()}});
$('projectsView').addEventListener('change',event=>{if(event.target.id==='requirementVersionSelect'){state.selectedRequirementId=event.target.value;renderRequirementsTab()}});
$('requirementLibraryView').addEventListener('change',event=>{if(event.target.id==='requirementProjectFilter')document.querySelectorAll('[data-requirement-project]').forEach(x=>x.hidden=!!event.target.value&&x.dataset.requirementProject!==event.target.value)});
$('runsView').addEventListener('change',event=>{if(event.target.id==='runTypeFilter')renderRuns($('runsView'),event.target.value?state.runs.filter(x=>x.run_type===event.target.value):state.runs)});
$('headerAction').addEventListener('click',()=>{if(state.view==='projects'){if(state.projectId)switchTab('inputs');else newProjectDialog()}else if(state.view==='factor-library')factorDialog();else if(state.view==='alpha-library')alphaDialog();else if(state.view==='requirement-library'){if(state.projectId)requirementDialog();else notify('请先选择项目',true)}else loadBase().catch(e=>notify(e.message,true))});
$('refreshAll').addEventListener('click',()=>loadBase().then(()=>notify('Research 数据已同步')).catch(e=>notify(e.message,true)));
$('closeEditorDialog')?.addEventListener('click',()=>$('editorDialog').close());
$('closeDrawer').addEventListener('click',closeDrawer);$('drawerScrim').addEventListener('click',closeDrawer);
loadBase().catch(error=>notify(`加载失败：${error.message}`,true));
